<?php
namespace App\Modules\Sales\Application;
use App\Models\User;use App\Modules\Catalog\Domain\Models\ProductPresentation;use App\Modules\Identity\Domain\Models\AuthorizationRequest;use App\Modules\Inventory\Application\ConvertPackage;use App\Modules\Inventory\Domain\Enums\PackageConversionType;use App\Modules\Inventory\Domain\Models\InventoryBalance;use DomainException;
class EnsureSaleInventory {public function __construct(private readonly ConvertPackage $convert){}public function execute(ProductPresentation $presentation,string $quantity,string $ownReserved,User $actor,?AuthorizationRequest $authorization=null):void{$balance=InventoryBalance::query()->firstOrCreate(['presentation_id'=>$presentation->id],['physical_quantity'=>0,'reserved_quantity'=>0,'average_unit_cost'=>0]);$freeRequired=max(0,(float)$quantity-(float)$ownReserved);$available=(float)$balance->availableQuantity();if($available<$freeRequired){$short=$freeRequired-$available;$package=ProductPresentation::query()->with(['packageComponents'=>fn($q)=>$q->where('component_presentation_id',$presentation->id),'inventoryBalance'])->where('item_id',$presentation->item_id)->whereHas('packageComponents',fn($q)=>$q->where('component_presentation_id',$presentation->id))->where('is_active',true)->get()->first(function($p)use($short){$component=(float)$p->packageComponents->first()->quantity;$available=(float)($p->inventoryBalance?->availableQuantity()??0);return $component>0&&$available>=ceil($short/$component);});if($package){$component=(float)$package->packageComponents->first()->quantity;$this->convert->execute($package,PackageConversionType::Disassembly,(string)ceil($short/$component),$actor,$authorization);$balance->refresh();$available=(float)$balance->availableQuantity();}}if($available<$freeRequired){if(!$authorization?->isUsable()||$authorization->approval_permission!=='inventory.authorize-negative')throw new DomainException("Inventario insuficiente para {$presentation->name}.");}}}
